layout=sfdp;
splines="polyline";
"n0" [];
"n1" [height="1.64"];
"n8" [];
"n10" [];
"n14" [];
"n15";
"n16" [];
"n17" [];
"n18" [];
"n0" -- subgraph "s3" {"n20" "n9" "n5"};
